#!/usr/bin/env python3
"""Test host reachability per definition of done."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "addr": "10.1.1.10", "guest": False},
    "B1-PC2": {"host": "192.168.122.32", "addr": "10.1.1.11", "guest": False},
    "B2-PC1": {"host": "192.168.122.33", "addr": "10.1.2.10", "guest": False},
    "B2-PC2": {"host": "192.168.122.34", "addr": "10.1.2.11", "guest": False},
    "B3-PC1": {"host": "192.168.122.35", "addr": "10.1.3.10", "guest": False},
    "B3-PC2": {"host": "192.168.122.36", "addr": "10.1.3.11", "guest": False},
    "B4-PC1": {"host": "192.168.122.37", "addr": "10.2.1.10", "guest": False},
    "B4-PC2": {"host": "192.168.122.38", "addr": "10.2.1.11", "guest": False},
    "B4-PC3": {"host": "192.168.122.39", "addr": "10.2.2.10", "guest": True},
    "B4-PC4": {"host": "192.168.122.40", "addr": "10.2.2.11", "guest": True},
}

NON_GUEST = [n for n, h in HOSTS.items() if not h["guest"]]
GUEST = [n for n, h in HOSTS.items() if h["guest"]]

def ping_from(src_name, targets):
    """Ping a list of target IPs from src. Returns list of (target_name, target_ip, success)."""
    info = HOSTS[src_name]
    results = []
    try:
        conn = ConnectHandler(host=info["host"], device_type="linux", username="root", password="alpine")
        for tgt_name, tgt_ip in targets:
            out = conn.send_command(f"ping -c 2 -W 2 {tgt_ip}", read_timeout=15)
            success = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
            results.append((tgt_name, tgt_ip, success))
        conn.disconnect()
    except Exception as e:
        for tgt_name, tgt_ip in targets:
            results.append((tgt_name, tgt_ip, False))
    return src_name, results

def main():
    all_results = {}

    # Build test plan for each host
    test_plan = {}
    for src in HOSTS:
        targets = []
        # Ping all other hosts
        for dst in HOSTS:
            if dst != src:
                targets.append((dst, HOSTS[dst]["addr"]))
        # Ping internet targets
        targets.append(("8.8.8.8", "8.8.8.8"))
        targets.append(("1.1.1.1", "1.1.1.1"))
        test_plan[src] = targets

    # Run in parallel
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for src, targets in test_plan.items():
            futures.append(pool.submit(ping_from, src, targets))
        for f in as_completed(futures):
            src, results = f.result()
            all_results[src] = results

    # Print results
    print("\n=== HOST REACHABILITY MATRIX ===\n")

    # Non-guest to non-guest (should all pass)
    print("--- Non-guest to non-guest (expect: PASS) ---")
    fail_count = 0
    pass_count = 0
    for src in NON_GUEST:
        for tgt_name, tgt_ip, success in all_results[src]:
            if tgt_name in NON_GUEST:
                status = "PASS" if success else "FAIL"
                if not success:
                    fail_count += 1
                    print(f"  {src} -> {tgt_name} ({tgt_ip}): {status}")
                else:
                    pass_count += 1
    print(f"  Total: {pass_count} PASS, {fail_count} FAIL (out of {pass_count+fail_count})")

    # Guest to guest (should pass)
    print("\n--- Guest to guest (expect: PASS) ---")
    for src in GUEST:
        for tgt_name, tgt_ip, success in all_results[src]:
            if tgt_name in GUEST:
                status = "PASS" if success else "FAIL"
                print(f"  {src} -> {tgt_name} ({tgt_ip}): {status}")

    # Guest to non-guest (should fail)
    print("\n--- Guest to non-guest (expect: FAIL) ---")
    fail_count = 0
    unexpected = 0
    for src in GUEST:
        for tgt_name, tgt_ip, success in all_results[src]:
            if tgt_name in NON_GUEST:
                status = "PASS" if success else "FAIL"
                if success:
                    unexpected += 1
                    print(f"  UNEXPECTED: {src} -> {tgt_name} ({tgt_ip}): PASS (should be FAIL)")
                else:
                    fail_count += 1
    print(f"  Total: {fail_count} correctly blocked, {unexpected} unexpected passes (out of {fail_count+unexpected})")

    # Non-guest to guest (should fail)
    print("\n--- Non-guest to guest (expect: FAIL) ---")
    fail_count = 0
    unexpected = 0
    for src in NON_GUEST:
        for tgt_name, tgt_ip, success in all_results[src]:
            if tgt_name in GUEST:
                status = "PASS" if success else "FAIL"
                if success:
                    unexpected += 1
                    print(f"  UNEXPECTED: {src} -> {tgt_name} ({tgt_ip}): PASS (should be FAIL)")
                else:
                    fail_count += 1
    print(f"  Total: {fail_count} correctly blocked, {unexpected} unexpected passes (out of {fail_count+unexpected})")

    # Internet reachability (all should pass)
