}

NON_GUEST = [n for n, h in HOSTS.items() if not h["guest"]]
GUEST = [n for n, h in HOSTS.items() if h["guest"]]

def ping_ok(output):
    return " 0% packet loss" in output

def ping_one(src_name, tgt_ip):
    info = HOSTS[src_name]
    try:
        conn = ConnectHandler(host=info["host"], device_type="linux", username="root", password="alpine")
        out = conn.send_command(f"ping -c 2 -W 2 {tgt_ip}", read_timeout=15)
        conn.disconnect()
        return ping_ok(out)
    except:
        return False

def main():
    # Test 1: Non-guest to non-guest (parallel, expect PASS)
    print("=== Non-guest to non-guest (expect: PASS) ===")
    pairs = [(s, d) for s in NON_GUEST for d in NON_GUEST if s != d]
    pass_c = fail_c = 0
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = {pool.submit(ping_one, s, HOSTS[d]["addr"]): (s, d) for s, d in pairs}
        for f in as_completed(futures):
            s, d = futures[f]
            if f.result():
                pass_c += 1
            else:
                fail_c += 1
                print(f"  FAIL: {s} -> {d} ({HOSTS[d]['addr']})")
    print(f"  {pass_c} PASS, {fail_c} FAIL (out of {pass_c+fail_c})")

    # Test 2: Guest to guest (expect PASS)
    print("\n=== Guest to guest (expect: PASS) ===")
    for src in GUEST:
        for dst in GUEST:
            if src != dst:
                r = ping_one(src, HOSTS[dst]["addr"])
                print(f"  {src} -> {dst}: {'PASS' if r else 'FAIL'}")

    # Test 3: Guest to non-guest (expect FAIL)
    print("\n=== Guest to non-guest (expect: FAIL) ===")
    blocked = unexpected = 0
    for src in GUEST:
        for dst in NON_GUEST:
            r = ping_one(src, HOSTS[dst]["addr"])
            if r:
                unexpected += 1
                print(f"  UNEXPECTED PASS: {src} -> {dst} ({HOSTS[dst]['addr']})")
            else:
                blocked += 1
    print(f"  {blocked} blocked, {unexpected} unexpected passes (out of {blocked+unexpected})")

    # Test 4: Non-guest to guest (expect FAIL)
    print("\n=== Non-guest to guest (expect: FAIL) ===")
    blocked = unexpected = 0
    for src in NON_GUEST:
        for dst in GUEST:
            r = ping_one(src, HOSTS[dst]["addr"])
            if r:
                unexpected += 1
                print(f"  UNEXPECTED PASS: {src} -> {dst} ({HOSTS[dst]['addr']})")
            else:
                blocked += 1
    print(f"  {blocked} blocked, {unexpected} unexpected passes (out of {blocked+unexpected})")

    # Test 5: Internet (parallel, expect PASS)
    print("\n=== Internet reachability (expect: PASS) ===")
    pass_c = fail_c = 0
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {}
        for src in HOSTS:
            for tgt in ["8.8.8.8", "1.1.1.1"]:
                futures[pool.submit(ping_one, src, tgt)] = (src, tgt)
        for f in as_completed(futures):
            s, t = futures[f]
            if f.result():
                pass_c += 1
            else:
                fail_c += 1
                print(f"  FAIL: {s} -> {t}")
    print(f"  {pass_c}/{pass_c+fail_c} PASS")

